import{_ as t,o as a,c as o,a6 as r}from"./chunks/framework.DMOj2-2K.js";const g=JSON.parse('{"title":"Why Cluub","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),n={name:"guide/introduction.md"};function d(s,e,i,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="why-cluub" tabindex="-1">Why Cluub <a class="header-anchor" href="#why-cluub" aria-label="Permalink to &quot;Why Cluub&quot;">​</a></h1><p>Today a web feature means learning JavaScript, TypeScript, React, a router, a state library, an HTTP framework, an ORM, a validation library, a test runner and an AI SDK, and then wiring them together. Every team wires them differently, and AI tools copy whichever style they saw last.</p><p><strong>Cluub is one small language that covers all of it.</strong> You describe <em>what</em> the feature is; Cluub produces the frontend, the backend and the tests.</p><h2 id="why-the-name-cluub" tabindex="-1">Why the name Cluub <a class="header-anchor" href="#why-the-name-cluub" aria-label="Permalink to &quot;Why the name Cluub&quot;">​</a></h2><p><strong>Cluub</strong> <em>clubs together</em> the three things every modern app needs: the <strong>frontend</strong>, the <strong>backend</strong> and <strong>AI</strong>. Instead of three languages, three frameworks and the glue between them, you write one structured language and Cluub builds all three.</p><p>The logo hides a small joke: the <strong>uu</strong> in the middle of <em>cluub</em> becomes the happy closed eyes of a cat. Friendly, curious and quick is how Cluub should feel. See <a href="/brand">Brand &amp; logo</a>.</p><p>Cluub files end in <strong><code>.clb</code></strong>, the command is <strong><code>cluub</code></strong>, the code lives at <strong><a href="https://github.com/cluub-lang/cluub" target="_blank" rel="noreferrer">github.com/cluub-lang/cluub</a></strong> and these docs at <strong><a href="https://cluub-lang.github.io/" target="_blank" rel="noreferrer">cluub-lang.github.io</a></strong>.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ol><li><strong>Reads like a prompt.</strong> Words instead of symbols: <code>is not empty</code>, <code>ask ai</code>, <code>on click save</code>. If you can write a clear request to an AI assistant, you can read Cluub.</li><li><strong>One way to do things.</strong> One folder layout, one layer architecture, one naming style, all enforced by the compiler. Code written by a senior developer, a junior, a product owner or an AI looks the same.</li><li><strong>Safe by default.</strong> Data is validated at every boundary, secrets can&#39;t reach the browser, and errors are precise with a hint to fix them.</li><li><strong>AI-native.</strong> AI calls, structured AI output and AI-written code are first-class, and the compiler checks AI-written code like any other.</li><li><strong>Zero dependencies.</strong> Your app doesn&#39;t need <code>npm install</code>. The output is plain JavaScript.</li></ol><h2 id="what-you-get-in-the-box" tabindex="-1">What you get in the box <a class="header-anchor" href="#what-you-get-in-the-box" aria-label="Permalink to &quot;What you get in the box&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You&#39;d normally need</th><th>Cluub</th></tr></thead><tbody><tr><td>React / Vue + router + state lib</td><td><code>page</code>, <code>component</code>, <code>layout</code>, <code>state</code></td></tr><tr><td>Express / Fastify + validation</td><td><code>api</code> with typed, validated parameters</td></tr><tr><td>ORM / repository layer</td><td><code>store</code> (memory or file today, databases on the roadmap)</td></tr><tr><td>Axios / fetch wrappers</td><td><code>client</code> (network layer)</td></tr><tr><td>OpenAI / Anthropic SDKs</td><td><code>ask ai</code> for Claude, OpenAI, Gemini and Ollama</td></tr><tr><td>Jest / Vitest / Playwright</td><td><code>test</code>, plus automatically generated tests</td></tr><tr><td>Docs for non-developers</td><td>`cluub explain --for po</td></tr></tbody></table><h2 id="shorter-learning-curve-than-react" tabindex="-1">Shorter learning curve than React <a class="header-anchor" href="#shorter-learning-curve-than-react" aria-label="Permalink to &quot;Shorter learning curve than React&quot;">​</a></h2><p>To be productive in React you need JSX, hooks and their rules, effects, props vs state, a router, data fetching, async/await, a bundler and TypeScript. In Cluub, a beginner learns <strong>6 ideas</strong>: <code>model</code>, <code>service</code>, <code>api</code>, <code>page</code>, <code>state</code> + <code>action</code>, and <code>view</code>. Everything else (awaiting, re-rendering, validation, error display, wiring dependencies) is automatic.</p><h2 id="solid-oop-and-design-patterns-built-in" tabindex="-1">SOLID, OOP and design patterns, built in <a class="header-anchor" href="#solid-oop-and-design-patterns-built-in" aria-label="Permalink to &quot;SOLID, OOP and design patterns, built in&quot;">​</a></h2><p>You don&#39;t have to remember them, because the structure applies them for you:</p><table tabindex="0"><thead><tr><th>Principle / pattern</th><th>How Cluub applies it</th></tr></thead><tbody><tr><td><strong>Single Responsibility</strong></td><td>Each declaration kind does one job; warnings W102/W103 flag oversized actions and services</td></tr><tr><td><strong>Open/Closed</strong></td><td>Add behavior by adding services or components, not by editing others</td></tr><tr><td><strong>Liskov / Interface Segregation</strong></td><td>Small typed actions; <code>uses</code> names the exact dependencies</td></tr><tr><td><strong>Dependency Inversion</strong></td><td><code>uses</code> declares dependencies; a container injects them, and tests swap in fakes (in-memory stores, fake AI)</td></tr><tr><td><strong>Encapsulation (OOP)</strong></td><td>Models validate themselves; services hide stores from apis and pages</td></tr><tr><td><strong>Repository pattern</strong></td><td><code>store</code></td></tr><tr><td><strong>Service layer / Facade</strong></td><td><code>service</code></td></tr><tr><td><strong>Adapter / Gateway</strong></td><td><code>client</code>, and the AI provider abstraction</td></tr><tr><td><strong>MVC / MVVM</strong></td><td><code>model</code> + <code>page</code> state/actions + <code>view</code></td></tr><tr><td><strong>Container / Presentational</strong></td><td>Pages own data; components only display it (<code>takes</code>)</td></tr><tr><td><strong>Observer</strong></td><td>Reactive state: change it and the view updates</td></tr><tr><td><strong>Strategy</strong></td><td><code>ask ai ... using &quot;openai&quot;</code> swaps providers without code changes</td></tr><tr><td><strong>Composite</strong></td><td>Layouts, pages and components nest</td></tr></tbody></table>',16)])])}const p=t(n,[["render",d]]);export{g as __pageData,p as default};
